settings.custom_css:
/* =========================================================
   RAMIS SHOP — PREMIUM PAYMENT HERO
   Root: 81846b2
   Theme: Premium / Modern / RTL / E-Commerce
   ========================================================= */


/* =========================================================
   01 — VARIABLES
   ========================================================= */

selector {
    --ramis-primary: #006660;
    --ramis-primary-dark: #003F3C;
    --ramis-primary-deep: #00332F;
    --ramis-secondary: #004F4B;
    --ramis-gold: #FFCE3A;

    --ramis-white: #FFFFFF;
    --ramis-text-soft: rgba(255,255,255,.76);

    --ramis-radius-desktop: 30px;
    --ramis-radius-mobile: 22px;

    position: relative;
    isolation: isolate;
    overflow: hidden;

    width: 100%;

    background:
        radial-gradient(
            circle at 88% 12%,
            rgba(255,206,58,.13),
            transparent 28%
        ),
        radial-gradient(
            circle at 8% 88%,
            rgba(0,180,165,.16),
            transparent 34%
        ),
        linear-gradient(
            135deg,
            var(--ramis-primary-dark) 0%,
            var(--ramis-primary) 52%,
            var(--ramis-primary-deep) 100%
        );

    border-radius:
        0 0
        var(--ramis-radius-desktop)
        var(--ramis-radius-desktop);

    box-shadow:
        0 22px 60px rgba(0,63,60,.18);

    transition:
        box-shadow .4s ease,
        background-position .6s ease;
}


/* =========================================================
   02 — ATMOSPHERIC BACKGROUND
   ========================================================= */

selector::before {
    content: "";
    position: absolute;

    width: 420px;
    height: 420px;

    top: -220px;
    right: -130px;

    background:
        radial-gradient(
            circle,
            rgba(255,206,58,.13) 0%,
            rgba(255,206,58,.045) 35%,
            transparent 70%
        );

    filter: blur(18px);

    pointer-events: none;
    z-index: 0;
}


selector::after {
    content: "";
    position: absolute;

    width: 380px;
    height: 380px;

    left: -180px;
    bottom: -230px;

    background:
        radial-gradient(
            circle,
            rgba(0,210,190,.14) 0%,
            rgba(0,180,165,.05) 40%,
            transparent 72%
        );

    filter: blur(22px);

    pointer-events: none;
    z-index: 0;
}


/* =========================================================
   03 — CONTENT LAYER
   ========================================================= */

selector > .elementor-element-5561b0b,
selector > .elementor-element-38e1baa {
    position: relative;
    z-index: 2;
}


/* =========================================================
   04 — TEXT CONTAINER
   ========================================================= */

selector .elementor-element-5561b0b {
    position: relative;

    padding:
        clamp(28px, 4vw, 58px)
        clamp(24px, 5vw, 72px);

    text-align: right;

    transition:
        transform .45s cubic-bezier(.2,.8,.2,1);
}


/* Subtle glass panel */
selector .elementor-element-5561b0b::before {
    content: "";

    position: absolute;
    inset: 12px;

    border:
        1px solid rgba(255,255,255,.075);

    border-radius: 24px;

    background:
        linear-gradient(
            135deg,
            rgba(255,255,255,.045),
            rgba(255,255,255,.012)
        );

    pointer-events: none;
}


/* =========================================================
   05 — TITLE
   ========================================================= */

selector .elementor-element-6599be5 {
    position: relative;
    z-index: 1;

    margin: 0 0 16px;

    text-align: right;
}


selector .elementor-element-6599be5 p {
    position: relative;

    display: inline-block;

    margin: 0;

    color: #FFFFFF !important;

    font-size: clamp(32px, 4vw, 46px);

    font-weight: 900;

    line-height: 1.4;

    letter-spacing: -.5px;

    text-shadow:
        0 5px 22px rgba(0,0,0,.20);
}


/* =========================================================
   06 — GOLD TITLE ACCENT
   ========================================================= */

selector .elementor-element-6599be5 p::after {
    content: "";

    display: block;

    width: 55px;
    height: 4px;

    margin-top: 14px;

    background: var(--ramis-gold);

    border-radius: 20px;

    box-shadow:
        0 4px 16px rgba(255,206,58,.25);

    transform-origin: right center;

    transition:
        width .4s cubic-bezier(.2,.8,.2,1),
        box-shadow .4s ease;
}


/* Accent interaction */
selector:hover .elementor-element-6599be5 p::after {
    width: 82px;

    box-shadow:
        0 5px 20px rgba(255,206,58,.36);
}


/* =========================================================
   07 — DESCRIPTION
   ========================================================= */

selector .elementor-element-b84fdca {
    position: relative;
    z-index: 1;

    max-width: 540px;

    margin-top: 6px;

    text-align: right;
}


selector .elementor-element-b84fdca p {
    margin: 0;

    color: var(--ramis-text-soft) !important;

    font-size: 15px;

    font-weight: 500;

    line-height: 2.15;

    letter-spacing: 0;

    text-shadow:
        0 2px 10px rgba(0,0,0,.12);

    transition:
        color .35s ease;
}


selector:hover .elementor-element-b84fdca p {
    color: rgba(255,255,255,.88) !important;
}


/* =========================================================
   08 — IMAGE CONTAINER
   ========================================================= */

selector .elementor-element-38e1baa {
    position: relative;

    padding: 18px;

    perspective: 1000px;

    transition:
        transform .45s cubic-bezier(.2,.8,.2,1);
}


/* Premium outer frame */
selector .elementor-element-38e1baa::before {
    content: "";

    position: absolute;

    inset: 8px;

    border:
        1px solid rgba(255,206,58,.27);

    border-radius: 25px;

    background:
        linear-gradient(
            135deg,
            rgba(255,206,58,.055),
            transparent 45%,
            rgba(255,255,255,.035)
        );

    pointer-events: none;

    transition:
        border-color .4s ease,
        box-shadow .4s ease;
}


/* Decorative gold corner */
selector .elementor-element-38e1baa::after {
    content: "";

    position: absolute;

    width: 70px;
    height: 70px;

    top: 0;
    left: 0;

    border-top:
        2px solid rgba(255,206,58,.45);

    border-left:
        2px solid rgba(255,206,58,.45);

    border-radius: 16px 0 0 0;

    opacity: .7;

    pointer-events: none;

    transition:
        opacity .4s ease,
        width .4s ease,
        height .4s ease;
}


/* =========================================================
   09 — IMAGE WIDGET
   ========================================================= */

selector .elementor-element-b59678b {
    position: relative;
    z-index: 2;

    width: 100%;

    transform:
        rotate(2deg);

    transition:
        transform .5s cubic-bezier(.2,.8,.2,1),
        filter .4s ease;
}


/* Actual image */
selector .elementor-element-b59678b img {
    display: block;

    width: 100%;

    height: auto;

    border-radius: 20px;

    border:
        1px solid rgba(255,255,255,.16);

    box-shadow:
        0 25px 55px rgba(0,0,0,.30),
        0 8px 22px rgba(0,0,0,.12);

    background: rgba(255,255,255,.035);

    transition:
        transform .5s cubic-bezier(.2,.8,.2,1),
        box-shadow .5s ease,
        border-color .4s ease;
}


/* =========================================================
   10 — IMAGE HOVER
   ========================================================= */

selector .elementor-element-38e1baa:hover {
    transform:
        translateY(-4px);
}


selector .elementor-element-38e1baa:hover::before {
    border-color:
        rgba(255,206,58,.42);

    box-shadow:
        0 0 35px rgba(255,206,58,.08);
}


selector .elementor-element-38e1baa:hover::after {
    opacity: 1;

    width: 82px;
    height: 82px;
}


selector .elementor-element-38e1baa:hover
.elementor-element-b59678b {
    transform:
        rotate(0deg)
        translateY(-7px);
}


selector .elementor-element-38e1baa:hover
.elementor-element-b59678b img {
    border-color:
        rgba(255,206,58,.26);

    box-shadow:
        0 32px 65px rgba(0,0,0,.34),
        0 12px 28px rgba(0,0,0,.14);
}


/* =========================================================
   11 — DESKTOP BALANCE
   ========================================================= */

@media (min-width: 1025px) {

    selector {
        min-height: 300px;
    }

    selector .elementor-element-5561b0b {
        align-self: stretch;
        justify-content: center;
    }

    selector .elementor-element-38e1baa {
        display: flex;
        align-items: center;
        justify-content: center;
    }

    selector .elementor-element-b59678b {
        max-width: 92%;
    }
}


/* =========================================================
   12 — TABLET
   ========================================================= */

@media (min-width: 768px) and (max-width: 1024px) {

    selector {
        border-radius:
            0 0
            26px
            26px;
    }

    selector .elementor-element-5561b0b {
        padding:
            34px
            38px;
    }

    selector .elementor-element-6599be5 p {
        font-size: clamp(29px, 4vw, 38px);
    }

    selector .elementor-element-b84fdca {
        max-width: 460px;
    }

    selector .elementor-element-38e1baa {
        padding: 14px;
    }

    selector .elementor-element-b59678b {
        transform: rotate(1deg);
    }

    selector .elementor-element-38e1baa:hover
    .elementor-element-b59678b {
        transform:
            rotate(0deg)
            translateY(-4px);
    }
}


/* =========================================================
   13 — MOBILE
   ========================================================= */

@media (max-width: 767px) {

    selector {
        border-radius:
            0 0
            var(--ramis-radius-mobile)
            var(--ramis-radius-mobile);

        overflow: hidden;

        /* Mobile stacking is necessary for the
           two-column Hero structure */
        flex-direction: column;
    }


    selector::before {
        width: 260px;
        height: 260px;

        top: -140px;
        right: -100px;

        opacity: .65;

        filter: blur(24px);
    }


    selector::after {
        width: 240px;
        height: 240px;

        left: -120px;
        bottom: -150px;

        opacity: .55;

        filter: blur(25px);
    }


    /* -----------------------------------------
       TEXT
       ----------------------------------------- */

    selector .elementor-element-5561b0b {
        width: 100%;

        padding:
            30px
            22px
            20px;

        text-align: center;
    }


    selector .elementor-element-5561b0b::before {
        inset: 8px;

        border-radius: 19px;
    }


    selector .elementor-element-6599be5 {
        margin-bottom: 13px;

        text-align: center;
    }


    selector .elementor-element-6599be5 p {
        font-size: clamp(28px, 8vw, 34px);

        line-height: 1.45;

        letter-spacing: 0;
    }


    selector .elementor-element-6599be5 p::after {
        width: 48px;

        margin:
            11px auto 0;

        transform-origin: center;
    }


    selector:hover .elementor-element-6599be5 p::after {
        width: 68px;
    }


    selector .elementor-element-b84fdca {
        width: 100%;
        max-width: 100%;

        margin-top: 4px;

        text-align: center;
    }


    selector .elementor-element-b84fdca p {
        font-size: 14px;

        line-height: 2;
    }


    /* -----------------------------------------
       IMAGE
       ----------------------------------------- */

    selector .elementor-element-38e1baa {
        width: 100%;

        padding:
            12px
            18px
            24px;

        transform: none;
    }


    selector .elementor-element-38e1baa::before {
        inset: 5px;

        border-radius: 20px;

        opacity: .8;
    }


    selector .elementor-element-38e1baa::after {
        width: 48px;
        height: 48px;

        top: 2px;
        left: 10px;

        opacity: .5;
    }


    selector .elementor-element-b59678b {
        width: 100%;
        max-width: 100%;

        transform: none;
    }


    selector .elementor-element-b59678b img {
        border-radius: 16px;

        box-shadow:
            0 18px 38px rgba(0,0,0,.27);
    }


    selector .elementor-element-38e1baa:hover {
        transform: none;
    }


    selector .elementor-element-38e1baa:hover
    .elementor-element-b59678b {
        transform:
            translateY(-3px);
    }
}


/* =========================================================
   14 — VERY SMALL PHONES
   ========================================================= */

@media (max-width: 380px) {

    selector .elementor-element-5561b0b {
        padding:
            26px
            18px
            16px;
    }


    selector .elementor-element-6599be5 p {
        font-size: 27px;
    }


    selector .elementor-element-b84fdca p {
        font-size: 13px;
        line-height: 1.95;
    }


    selector .elementor-element-38e1baa {
        padding:
            10px
            14px
            20px;
    }
}


/* =========================================================
   15 — REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

    selector,
    selector *,
    selector::before,
    selector::after {
        transition: none !important;
        animation: none !important;
    }

    selector .elementor-element-b59678b,
    selector .elementor-element-38e1baa {
        transform: none !important;
    }
}

/* حذف کامل بکگراند عکس */
.elementor-widget-image,
.elementor-widget-image .elementor-widget-container,
.elementor-widget-image img {
    background: transparent !important;
    background-color: transparent !important;
}

/* اطمینان از شفاف بودن خود تصویر */
.elementor-widget-image img {
    mix-blend-mode: normal !important;
}

/* =========================================================
   RAMIS CHECKOUT
   Premium RTL Checkout
   ========================================================= */
.woocommerce-checkout {
    --ramis-navy: #006660;
    --ramis-navy-dark: #004F4B;

    --ramis-blue: #006660;
    --ramis-blue-soft: #EAF4F3;

    --ramis-yellow: #FFCE3A;
    --ramis-yellow-soft: #FFF8E7;

    --ramis-bg: #F5F6F7;
    --ramis-card: #FFFFFF;

    --ramis-border: #E3E6E8;
    --ramis-input: #FFFFFF;

    --ramis-text: #1B252C;
    --ramis-muted: #7C858C;

    --ramis-radius: 8px;

    direction: rtl;
    background: var(--ramis-bg);
    color: var(--ramis-text);

    font-family: inherit;
}


/* =========================================================
   1. MAIN CHECKOUT GRID
   ========================================================= */

form.checkout.woocommerce-checkout {

    max-width: 1180px;

    margin: 40px auto;

    display: grid;

    grid-template-columns: minmax(0, 0.72fr) minmax(0, 1.28fr);

    grid-template-areas:
        "summary customer";

    gap: 24px;

    align-items: start;
}


/* =========================================================
   2. CUSTOMER DETAILS = RIGHT COLUMN
   ========================================================= */

#customer_details {

    grid-area: customer;

    width: 100%;

    display: block;

    margin: 0 !important;

    padding: 0 !important;
}


/* جلوگیری از استایل پیش‌فرض ووکامرس */

#customer_details .col-1,
#customer_details .col-2 {

    width: 100% !important;

    float: none !important;

    padding: 0 !important;

    margin: 0 !important;
}


/* =========================================================
   3. BILLING CARD
   ========================================================= */

.woocommerce-billing-fields {

    background: var(--ramis-card);

    padding: 28px;

    border-radius: var(--ramis-radius);

    box-shadow:
        0 4px 6px rgba(0,0,0,.06);

    margin: 0 !important;
}


/* =========================================================
   4. BILLING TITLE
   ========================================================= */

.woocommerce-billing-fields > h3 {

    display: none !important;
}


.checkout-titles {

    margin-bottom: 22px;
}


.checkout-titles h3 {

    display: flex;

    align-items: center;

    gap: 10px;

    margin: 0 !important;

    color: var(--ramis-navy);

    font-size: 18px;

    font-weight: 800;
}


/* icon/title marker */

.checkout-titles h3::before {

    content: "♙";

    display: flex;

    align-items: center;

    justify-content: center;

    width: 30px;

    height: 30px;

    border-radius: 50%;

    background: var(--ramis-blue-soft);

    color: var(--ramis-blue);

    font-size: 15px;
}


/* =========================================================
   5. BILLING FIELDS
   ========================================================= */

.woocommerce-billing-fields__field-wrapper {

    display: grid;

    grid-template-columns: repeat(2, minmax(0,1fr));

    gap: 17px 14px;
}


.woocommerce-billing-fields__field-wrapper
.form-row {

    width: 100% !important;

    float: none !important;

    margin: 0 !important;

    padding: 0 !important;
}


/* full width */

.woocommerce-billing-fields__field-wrapper
.form-row-wide {

    grid-column: 1 / -1;
}


/* =========================================================
   6. LABEL
   ========================================================= */

.woocommerce-checkout label {

    display: block;

    margin-bottom: 8px;

    color: var(--ramis-text);

    font-size: 13px;

    font-weight: 600;
}


.woocommerce-checkout label .required {

    color: #D9534F;
}


.woocommerce-checkout label .optional {

    color: var(--ramis-muted);

    font-size: 11px;

    font-weight: 400;
}


/* =========================================================
   7. INPUTS
   ========================================================= */

.woocommerce-checkout
input.input-text,
.woocommerce-checkout
input[type="text"],
.woocommerce-checkout
input[type="email"],
.woocommerce-checkout
input[type="tel"],
.woocommerce-checkout
select,
.woocommerce-checkout
textarea {

    width: 100% !important;

    box-sizing: border-box;

    height: 48px;

    padding: 0 14px;

    background: #FFFFFF;

    border: 1px solid var(--ramis-border) !important;

    border-radius: var(--ramis-radius) !important;

    color: var(--ramis-text);

    font-family: inherit;

    font-size: 13px;

    outline: none;

    transition:
        border-color .2s ease,
        box-shadow .2s ease,
        background .2s ease;
}


/* focus */

.woocommerce-checkout
input.input-text:focus,
.woocommerce-checkout
input[type="text"]:focus,
.woocommerce-checkout
input[type="email"]:focus,
.woocommerce-checkout
input[type="tel"]:focus,
.woocommerce-checkout
select:focus,
.woocommerce-checkout
textarea:focus {

    border-color: var(--ramis-blue) !important;

    box-shadow:
        0 0 0 3px rgba(39,184,199,.10);

    background: #fff;
}


/* =========================================================
   8. ORDER REVIEW
   ========================================================= */

/*
   این قسمت عمداً display:contents است تا
   جدول سفارش و payment بتوانند در grid اصلی
   قرار بگیرند.
*/

#order_review {

    display: contents;
}


/* =========================================================
   9. ORDER TABLE = LEFT COLUMN
   ========================================================= */

.woocommerce-checkout-review-order-table {

    grid-area: summary;

    width: 100%;

    align-self: start;

    background: var(--ramis-card);

    padding: 24px;

    border-radius: var(--ramis-radius);

    box-shadow:
        0 4px 6px rgba(0,0,0,.06);

    border-collapse: separate !important;

    border-spacing: 0 !important;

    margin: 0 !important;
}


/* =========================================================
   10. ORDER TITLE
   ========================================================= */

#order_payment_heading {

    display: none !important;
}


#order_review_heading {

    display: none !important;
}


/* =========================================================
   11. ORDER HEADER
   ========================================================= */

.woocommerce-checkout-review-order-table thead {

    background: transparent;
}


.woocommerce-checkout-review-order-table thead th {

    padding: 0 0 18px;

    border: 0 !important;

    color: var(--ramis-navy);

    font-size: 17px;

    font-weight: 800;
}


/* change first header */

.woocommerce-checkout-review-order-table thead th:first-child {

    font-size: 0;
}


.woocommerce-checkout-review-order-table thead th:first-child::before {

    content: "☷  خلاصه سفارش";

    font-size: 17px;

    color: var(--ramis-navy);
}


.woocommerce-checkout-review-order-table thead th:last-child {

    font-size: 0;
}


/* =========================================================
   12. PRODUCTS
   ========================================================= */

.woocommerce-checkout-review-order-table tbody tr {

    border: 0 !important;
}


.woocommerce-checkout-review-order-table tbody td {

    padding: 15px 0;

    border: 0 !important;

    border-bottom: 1px solid #F0F1F2 !important;

    vertical-align: middle;
}


.woocommerce-checkout-review-order-table
.product-name {

    color: var(--ramis-text);

    text-align: right;

    font-size: 13px;

    font-weight: 500;
}


.woocommerce-checkout-review-order-table
.product-total {

    text-align: left;

    white-space: nowrap;

    color: var(--ramis-navy);

    font-size: 13px;

    font-weight: 700;
}


/* quantity */

.woocommerce-checkout-review-order-table
.product-quantity {

    display: inline-block;

    margin-right: 5px;

    color: var(--ramis-muted);

    font-size: 11px;

    font-weight: 500;
}


/* =========================================================
   13. SUBTOTAL
   ========================================================= */

.woocommerce-checkout-review-order-table
tfoot th,
.woocommerce-checkout-review-order-table
tfoot td {

    border: 0 !important;

    padding: 10px 0;

    font-size: 13px;
}


.woocommerce-checkout-review-order-table
.cart-subtotal th {

    color: var(--ramis-muted);

    font-weight: 500;
}


.woocommerce-checkout-review-order-table
.cart-subtotal td {

    color: var(--ramis-text);

    font-weight: 700;
}


/* =========================================================
   14. FINAL TOTAL
   ========================================================= */

.woocommerce-checkout-review-order-table
.order-total {

    margin-top: 10px;

    background: var(--ramis-blue-soft);
}


.woocommerce-checkout-review-order-table
.order-total th {

    padding: 16px 14px !important;

    color: var(--ramis-navy);

    border-radius: 0 8px 8px 0 !important;

    font-size: 14px;

    font-weight: 800;
}


.woocommerce-checkout-review-order-table
.order-total td {

    padding: 16px 14px !important;

    color: var(--ramis-blue);

    border-radius: 8px 0 0 8px !important;

    font-size: 20px;

    font-weight: 900;

    text-align: left !important;
}


/* =========================================================
   15. PAYMENT CARD
   ========================================================= */

#payment {

    grid-column: 2;

    grid-row: 2;

    width: 100%;

    margin: 0 !important;

    padding: 28px !important;

    background: var(--ramis-card) !important;

    border-radius: var(--ramis-radius);

    box-shadow:
        0 4px 6px rgba(0,0,0,.06);
}


/* =========================================================
   16. PAYMENT TITLE
   ========================================================= */

#payment .checkout-titles {

    margin-bottom: 20px;
}


#payment .checkout-titles h3 {

    color: var(--ramis-navy);
}


/* =========================================================
   17. PAYMENT METHODS
   ========================================================= */

#payment ul.payment_methods {

    padding: 0 !important;

    margin: 0 !important;

    border: 0 !important;

    list-style: none;
}


#payment ul.payment_methods > li {

    margin: 0 0 12px;

    padding: 17px;

    background: #fff;

    border: 1px solid var(--ramis-border);

    border-radius: var(--ramis-radius);

    transition: .2s ease;
}


/* selected */

#payment ul.payment_methods > li:has(input[type="radio"]:checked) {

    border: 2px solid var(--ramis-yellow);

    background: var(--ramis-yellow-soft);
}


/* radio */

#payment input[type="radio"] {

    accent-color: var(--ramis-navy);

    margin-left: 8px;
}


/* =========================================================
   18. NO PAYMENT MESSAGE
   ========================================================= */

#payment .woocommerce-info {

    margin: 0;

    padding: 14px;

    background: #F7F8F9;

    border: 0 !important;

    border-radius: var(--ramis-radius);

    color: var(--ramis-muted);

    font-size: 12px;

    line-height: 2;
}


/* =========================================================
   19. PRIVACY
   ========================================================= */

.woocommerce-privacy-policy-text {

    margin: 18px 0 12px;

    color: var(--ramis-muted);

    font-size: 11px;

    line-height: 2;
}


.woocommerce-privacy-policy-text a {

    color: var(--ramis-blue);

    font-weight: 700;

    text-decoration: none;
}


/* =========================================================
   20. TERMS
   ========================================================= */

.woocommerce-form__label-for-checkbox {

    display: flex !important;

    align-items: flex-start;

    gap: 9px;

    margin: 12px 0 0;

    padding: 13px;

    background: #F8F9FA;

    border-radius: var(--ramis-radius);

    cursor: pointer;

    line-height: 1.8;
}


.woocommerce-form__input-checkbox {

    width: 18px !important;

    height: 18px !important;

    min-width: 18px;

    margin: 2px 0 0 !important;

    accent-color: var(--ramis-blue);
}


.woocommerce-terms-and-conditions-checkbox-text {

    color: var(--ramis-text);

    font-size: 12px;

    font-weight: 500;
}


.woocommerce-terms-and-conditions-checkbox-text a {

    color: var(--ramis-blue);

    font-weight: 700;

    text-decoration: none;
}


/* =========================================================
   21. PLACE ORDER
   ========================================================= */

#place_order {

    width: 100% !important;

    height: 56px;

    margin-top: 18px;

    padding: 0 20px;

    border: 0 !important;

    border-radius: var(--ramis-radius);

    background: var(--ramis-navy) !important;

    color: #fff !important;

    font-family: inherit;

    font-size: 14px;

    font-weight: 800;

    cursor: pointer;

    transition:
        background .2s ease,
        transform .2s ease,
        box-shadow .2s ease;
}


#place_order:hover {

    background: var(--ramis-navy-dark) !important;

    transform: translateY(-2px);

    box-shadow:
        0 8px 20px rgba(23,42,58,.18);
}


/* =========================================================
   22. BUTTON ARROW
   ========================================================= */

#place_order::after {

    content: "←";

    display: inline-block;

    margin-right: 9px;

    font-size: 17px;

    transition: transform .2s ease;
}


#place_order:hover::after {

    transform: translateX(-4px);
}


/* =========================================================
   23. RTL PRICE
   ========================================================= */

.woocommerce-Price-amount {

    direction: ltr;

    unicode-bidi: plaintext;

    display: inline-block;
}


.woocommerce-Price-currencySymbol {

    margin-right: 4px;

    font-size: 10px;
}


/* =========================================================
   24. REMOVE OLD WOOCOMMERCE BORDERS
   ========================================================= */

.woocommerce-checkout
table,
.woocommerce-checkout
td,
.woocommerce-checkout
th {

    border: 0 !important;
}


/* =========================================================
   25. MOBILE
   ========================================================= */

@media (max-width: 767px) {

    form.checkout.woocommerce-checkout {

        display: flex;

        flex-direction: column;

        gap: 16px;

        margin: 20px 12px;
    }


    #customer_details {

        order: 1;
    }


    .woocommerce-checkout-review-order-table {

        order: 2;
    }


    #payment {

        order: 3;

        grid-column: auto;

        grid-row: auto;
    }


    .woocommerce-billing-fields {

        padding: 20px;
    }


    .woocommerce-billing-fields__field-wrapper {

        grid-template-columns: 1fr;

        gap: 14px;
    }


    .woocommerce-billing-fields__field-wrapper
    .form-row-wide {

        grid-column: auto;
    }


    #payment {

        padding: 20px !important;
    }


    .woocommerce-checkout-review-order-table {

        padding: 20px;
    }
}


/* =========================================================
   26. SMALL MOBILE
   ========================================================= */

@media (max-width: 480px) {

    form.checkout.woocommerce-checkout {

        margin: 14px 10px;
    }


    .woocommerce-billing-fields,
    #payment,
    .woocommerce-checkout-review-order-table {

        padding: 17px !important;

        border-radius: 8px;
    }


    .woocommerce-checkout-review-order-table
    .order-total td {

        font-size: 17px;
    }


    #place_order {

        height: 54px;
    }
}
